SELECT 
	imo.imov_id AS "MATRICULA",
	cli.clie_nmcliente AS "CLIENTE",
	cli.clie_dsemail AS "EMAIL",
	con_atraso.min_venc AS "VENCIMENTO",
	con_atraso.valor AS "VALOR",
	'' AS "COD BARRAS",
	con_atraso.min AS "REFERENCIA",
	'('||cfn.cfon_cdddd||') '||cfn.cfon_nnfone AS "TELEFONE",
	loc.loca_nmlocalidade AS "LOCALIDADE",
	une.uneg_nmunidadenegocio AS "UNIDADE",
	con_atraso.qtd AS "QTD DEBITOS",
	con_atraso.valor AS "VALOR DEBITOS"
FROM
	cadastro.imovel imo
	INNER JOIN cadastro.cliente_imovel cim ON imo.imov_id = cim.imov_id AND cim.clim_dtrelacaofim IS NULL AND cim.clim_icnomeconta = 1
	INNER JOIN cadastro.localidade loc ON loc.loca_id = imo.loca_id
	INNER JOIN cadastro.unidade_negocio une ON une.uneg_id = loc.uneg_id
	INNER JOIN cadastro.cliente cli ON cli.clie_id = cim.clie_id
	INNER JOIN cadastro.cliente_fone cfn ON cfn.clie_id = cli.clie_id
	INNER JOIN con_atraso ON con_atraso.mat1 = imo.imov_id
WHERE
	cfn.cfon_id = (
			SELECT 
				MAX(cfn2.cfon_id) 
			FROM 
				cadastro.cliente_fone cfn2 
			WHERE 
				cfn2.clie_id = cli.clie_id
				AND LEFT(cfn2.cfon_nnfone,1) = '9'
				AND LENGTH(cfn2.cfon_nnfone)=9
				AND cfn2.cfon_cdddd IN ('98','99'))
	AND imo.iper_id <> 6
	AND con_atraso.valor > 0
	AND NOT EXISTS(
		SELECT
			*
		FROM
			cobranca.cobranca_situacao_hist csh
		WHERE
			csh.imov_id = imo.imov_id
			AND csh.cbsh_amcobrancaretirada IS NULL
		LIMIT 1
	)
	AND imo.imov_idcategoriaprincipal IN (1,2,3)
ORDER BY "VALOR" DESC